function issueTokens(user) {
  const access = jwt.sign(
    { sub: user.id, role: user.role },
    process.env.JWT_ACCESS_SECRET,
    { expiresIn: '15m' }
  );
  const refresh = jwt.sign(
    { sub: user.id, v: user.tokenVersion },
    process.env.JWT_REFRESH_SECRET,
    { expiresIn: '30d' }
  );
  return { access, refresh };
}

app.post('/auth/refresh', async (req, res) => {
  const token = req.cookies.refresh ?? req.body.refresh;
  let payload;
  try { payload = jwt.verify(token, process.env.JWT_REFRESH_SECRET); }
  catch { return res.status(401).json({ message: 'Session expired' }); }

  const user = await User.findById(payload.sub);
  if (!user || user.tokenVersion !== payload.v) {
    return res.status(401).json({ message: 'Session revoked' });
  }
  res.json(issueTokens(user));
});

const { OAuth2Client } = require('google-auth-library');
const google = new OAuth2Client();

async function verifyGoogle(idToken) {
  const ticket = await google.verifyIdToken({
    idToken,
    audience: [process.env.GOOGLE_WEB_CLIENT_ID, process.env.GOOGLE_IOS_CLIENT_ID]
  });
  const p = ticket.getPayload();
  return { providerId: p.sub, email: p.email, emailVerified: p.email_verified, name: p.name };
}

export function requireAuth(...roles) {
  return (req, res, next) => {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) return res.status(401).json({ message: 'Unauthorized' });
    try {
      req.user = jwt.verify(token, process.env.JWT_ACCESS_SECRET);
    } catch {
      return res.status(401).json({ message: 'Token expired' });
    }
    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json({ message: 'Forbidden' });
    }
    next();
  };
}

