app.post('/webhooks/stripe', express.raw({ type: 'application/json' }), async (req, res) => {
  const event = stripe.webhooks.constructEvent(
    req.body, req.headers['stripe-signature'], process.env.STRIPE_WEBHOOK_SECRET
  );
  if (await ProcessedEvent.exists({ id: event.id })) return res.sendStatus(200);

  if (event.type === 'customer.subscription.updated') {
    const sub = event.data.object;
    await Entitlement.updateOne(
      { userId: sub.metadata.userId },
      { plan: 'pro', source: 'stripe', status: mapStatus(sub.status),
        expiresAt: new Date(sub.current_period_end * 1000) },
      { upsert: true }
    );
  }
  await ProcessedEvent.create({ id: event.id });
  res.sendStatus(200);
});

io.use((socket, next) => {
  try {
    const token = socket.handshake.auth?.token;
    socket.user = jwt.verify(token, process.env.JWT_ACCESS_SECRET);
    next();
  } catch {
    next(new Error('unauthorized'));
  }
});

io.on('connection', (socket) => {
  const { sub: userId, role } = socket.user;
  socket.join(`user:${userId}`);
  if (role === 'admin') socket.join('admins');
});

